-- Delete meetings for Test sponsor
DELETE FROM meetings WHERE sponsorId IN (SELECT id FROM sponsors WHERE contactEmail = 'bobby@recruitmentevents.co' AND companyName = 'Test');

-- Delete rankings submissions for Test sponsor
DELETE FROM rankingsSubmissions WHERE sponsorId IN (SELECT id FROM sponsors WHERE contactEmail = 'bobby@recruitmentevents.co' AND companyName = 'Test');

-- Delete intake submissions for Test sponsor
DELETE FROM intakeSubmissions WHERE sponsorId IN (SELECT id FROM sponsors WHERE contactEmail = 'bobby@recruitmentevents.co' AND companyName = 'Test');

-- Delete Test sponsor
DELETE FROM sponsors WHERE contactEmail = 'bobby@recruitmentevents.co' AND companyName = 'Test';

-- Verify deletion
SELECT COUNT(*) as remaining_test_sponsors FROM sponsors WHERE contactEmail = 'bobby@recruitmentevents.co' AND companyName = 'Test';

